1	"use client";
2	
3	import {
4	  createContext,
5	  useContext,
6	  useState,
7	  useEffect,
8	  ReactNode,
9	} from "react";
10	import { Player } from "@/lib/types";
11	import { supabase } from "@/lib/supabase";
12	
13	const NAMES_KEY = "rechenheld_known_names";
14	
15	function getKnownNames(): string[] {
16	  const stored = localStorage.getItem(NAMES_KEY);
17	  return stored ? JSON.parse(stored) : [];
18	}
19	
20	function addKnownName(name: string) {
21	  const names = getKnownNames();
22	  if (!names.includes(name)) {
23	    names.push(name);
24	    localStorage.setItem(NAMES_KEY, JSON.stringify(names));
25	  }
26	}
27	
28	type PlayerContextType = {
29	  player: Player | null;
30	  knownNames: string[];
31	  login: (name: string) => Promise<void>;
32	  logout: () => Promise<void>;
33	  notificationsEnabled: boolean;
34	  subscribeToNotifications: () => Promise<boolean>;
35	};
36	
37	const PlayerContext = createContext<PlayerContextType>({
38	  player: null,
39	  knownNames: [],
40	  login: async () => {},
41	  logout: async () => {},
42	  notificationsEnabled: false,
43	  subscribeToNotifications: async () => false,
44	});
45	
46	export function usePlayer() {
47	  return useContext(PlayerContext);
48	}
49	
50	export function PlayerProvider({ children }: { children: ReactNode }) {
51	  const [player, setPlayer] = useState<Player | null>(null);
52	  const [knownNames, setKnownNames] = useState<string[]>([]);
53	  const [notificationsEnabled, setNotificationsEnabled] = useState(false);
54	
55	  useEffect(() => {
56	    setKnownNames(getKnownNames());
57	    const stored = localStorage.getItem("rechenheld_player");
58	    if (stored) {
59	      setPlayer(JSON.parse(stored));
60	    }
61	
62	    async function initServiceWorker() {
63	      if (!("serviceWorker" in navigator)) return;
64	      await navigator.serviceWorker.register("/sw.js").catch(console.error);
65	      const reg = await navigator.serviceWorker.ready;
66	      const sub = await reg.pushManager.getSubscription().catch(() => null);
67	      if (sub) setNotificationsEnabled(true);
68	    }
69	    initServiceWorker();
70	  }, []);
71	
72	  async function login(name: string) {
73	    const trimmed = name.trim();
74	    if (!trimmed) return;
75	
76	    const { data: existing } = await supabase
77	      .from("players")
78	      .select("id, name")
79	      .eq("name", trimmed)
80	      .single();
81	
82	    let p: Player;
83	    if (existing) {
84	      p = existing;
85	    } else {
86	      const { data: created, error } = await supabase
87	        .from("players")
88	        .insert({ name: trimmed })
89	        .select("id, name")
90	        .single();
91	      if (error) throw error;
92	      p = created;
93	    }
94	
95	    setPlayer(p);
96	    localStorage.setItem("rechenheld_player", JSON.stringify(p));
97	    addKnownName(trimmed);
98	    setKnownNames(getKnownNames());
99	  }
100	
101	  async function logout() {
102	    if ("serviceWorker" in navigator) {
103	      const reg = await navigator.serviceWorker.ready.catch(() => null);
104	      const sub = await reg?.pushManager.getSubscription().catch(() => null);
105	      if (sub) {
106	        await supabase.from("push_subscriptions").delete().eq("endpoint", sub.endpoint);
107	        await sub.unsubscribe();
108	      }
109	    }
110	    setNotificationsEnabled(false);
111	    setPlayer(null);
112	    localStorage.removeItem("rechenheld_player");
113	  }
114	
115	  async function subscribeToNotifications(): Promise<boolean> {
116	    if (!player || !("serviceWorker" in navigator) || !("PushManager" in window)) {
117	      return false;
118	    }
119	    try {
120	      const reg = await navigator.serviceWorker.ready;
121	      const existing = await reg.pushManager.getSubscription();
122	      const sub =
123	        existing ??
124	        (await reg.pushManager.subscribe({
125	          userVisibleOnly: true,
126	          applicationServerKey: process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY!,
127	        }));
128	
129	      const { error } = await supabase.from("push_subscriptions").upsert(
130	        {
131	          player_id: player.id,
132	          endpoint: sub.endpoint,
133	          p256dh: sub.toJSON().keys!.p256dh,
134	          auth: sub.toJSON().keys!.auth,
135	        },
136	        { onConflict: "endpoint" }
137	      );
138	
